from PIL import Image

# Check the training directory structure
train_path = 'data_small/training_set'
test_path = 'data_small/test_set'

print("Checking training directory:")
if os.path.exists(train_path):
    for root, dirs, files in os.walk(train_path):
        print(f"Directory: {root}")
        for f in files:
            file_path = os.path.join(root, f)
            print(f"  File: {f}")
            # Try to open the image
            try:
                img = Image.open(file_path)
                print(f"    Format: {img.format}, Size: {img.size}")
                img.close()
            except Exception as e:
                print(f"    Error reading: {e}")

print("\nChecking test directory:")
if os.path.exists(test_path):
